      else { $title = ''; }
      if ( isset( $instance['menu_label'] ) ) { $menu_label = $instance['menu_label']; }
      else { $menu_label = ''; }
      if ( isset( $instance['target'] ) ) { $target = $instance['target']; }
      else { $target = ''; }

      ?>
      <p>
        <label for="<?php echo $this->get_field_id( 'title' ); ?>"><?php _e( 'Título:' ); ?></label>
        <input class="widefat" id="<?php echo $this->get_field_id( 'title' ); ?>" name="<?php echo $this->get_field_name( 'title' ); ?>" type="text" value="<?php echo esc_attr( $title ); ?>">
      </p>
      <p>
        <label for="<?php echo $this->get_field_id( 'menu_label' ); ?>"><?php _e( 'Etiqueta del menú:' ); ?></label>
        <input class="widefat" id="<?php echo $this->get_field_id( 'menu_label' ); ?>" name="<?php echo $this->get_field_name( 'menu_label' ); ?>" type="text" value="<?php echo esc_attr( $menu_label ); ?>">
      </p>
      <p>
        <label for="<?php echo $this->get_field_id( 'target' ); ?>"><?php _e( 'Rellenar objetivo:' ); ?></label>
        <input class="widefat" id="<?php echo $this->get_field_id( 'target' ); ?>" name="<?php echo $this->get_field_name( 'target' ); ?>" type="text" value="<?php echo esc_attr( $target ); ?>">
      </p>
      <?php
    }

    function update( $new_instance, $old_instance ) {
      $instance = array();
      $instance['title'] = ( ! empty( $new_instance['title'] ) ) ? strip_tags( $new_instance['title'] ) : '';
      $instance['menu_label'] = ( ! empty( $new_instance['menu_label'] ) ) ? strip_tags( $new_instance['menu_label'] ) : '';
      $instance['target'] = ( ! empty( $new_instance['target'] ) ) ? strip_tags( $new_instance['target'] ) : '';

      return $instance;
    }

  }

  register_widget( 'My_Custom_Widget' );

  ?>
  ```

- Códigos cortos adicionales: Utiliza los hooks `add_shortcode()` y `register_shortcode_function()` para crear tus códigos cortos y vincularlas con tus funciones PHP. Aquí

  ```php
  <?php

  function my_custom_shortcode() {
