      .expect(createTestInvoiceQuery(invoiceData))
      .toExist();

    assertJ({ status })
      .expect(HttpStatus.CREATED)
      .isTrue();
  });
});

function createTestInvoiceQuery(invoiceData: any): string {
  return `SELECT * FROM ar_invoices WHERE vendor = '${
      invoiceData.vendor
    }' AND amount = ${invoiceData.amount} AND tax_rate = ${invoiceData.taxRate}`;
}
```

