import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.HttpStatus;
import org.springframework.test.context.TestPropertySource;

import com.imsl.ecb.entities.CommercialInvoiceEntity;
import com.imsl.ecb.services.CommercialInvoiceService;

import java.nio.charset.StandardCharsets;

@SpringBootTest
@TestPropertySource(locations = "classpath:test.properties")
public class CreateInvoiceSuccesfullyTest {

    private static final String CONTENT_TYPE = "application/json";
    private static final String ORACLE_API_KEY_HEADER = "oracle-api-key";
    private static final String ORACLE_API_INSTANCE_HEADER = "oracle-api-instance";
    private static final String ORACLE_APP_ID_HEADER = "oracle-app-id";
    private static final String ORACLE_TIMESTAMP_HEADER = " oracle-timestamp";
    private static final String ORACLE_SECURITY_TOKEN_HEADER = "oracle-security-token";

    @Autowired
    private CommercialInvoiceService commercialInvoiceService;

    @BeforeAll
    public static void setup() {
        ConfigurableRandomProvider randomProvider = new Jsr305RandomProvider();
        randomProvider.addProvider(new SinceJava8RandomProvider());
        randomProvider.addProvider(new SinceJava9RandomJavaProvider());
        RandomBeans.randomizeWith(randomProvider)
                .mapRandomizationOf(Collections.class, new ListRandomizer())
                .mapRandomizationOf(FieldValueMapper.class, alwaysStringFieldMapper())
                .useDefaultRandomnessAsDefault()
                .withCollectionSizeRandomizer(new CollectionsRandomizer()).create(CommercialInvoiceEntity.class);

        RandomJava.SeedSeedBased seeding = RandomJava.seedSeedBased();
        seeding.config().setSeed(RandomJava.defaultSeed);
        RandomJava.javaConfig().applyTo(RandomBeans.randomize());
    }

    @Test
    public void createInvoiceSuccesfully() {
        // Generate invoice data using Datafaker
        CommercialInvoiceEntity newInvoice = EnhancedRandomBeans.of(CommercialInvoiceEntity.class).exclude(CommercialInvoiceEntity::getEntityId).create();

        // Build HTTP request with invoice data
        StringEntity entity = new StringEntity(
                new InvoiceJsonBuilder(newInvoice).build(), StandardCharsets.UTF_8);
        HttpPost request = new HttpPost(INVOICE_SERVICE_URL);
        request.addHeader(HttpHeaders.CONTENT_TYPE, CONTENT_TYPE);
        request.addHeader(ORACLE_API_KEY_HEADER, System.getProperty("oracle_api_key"));
        request.addHeader(ORACLE_API_INSTANCE_HEADER, System.getProperty("oracle_api_instance"));
        request.addHeader(ORACLE_APP_ID_HEADER, System.getProperty("oracle_app_id"));
        request.addHeader(ORACLE_TIMESTAMP_HEADER, System.getProperty("oracle_timestamp"));
        request.addHeader(ORACLE_SECURITY_TOKEN_HEADER, System.getProperty("oracle_security_token"));
        request.setEntity(entity);

        try (CloseableHttpClient httpClient = HttpClients.createDefault()) {
            CloseableHttpResponse response = httpClient.execute(request);
            HttpEntity entityResponse = response.getEntity();

            // Verify HTTP response status code
            assertThat(response.getStatusLine().getStatusCode()).isEqualTo(HttpStatus.CREATED.value());

            // Verify invoice creation
            Long invoiceId = commercialInvoiceService.findByInvoiceNumber(newInvoice.getInvoiceNumber()).get().getId();
            assertThat(invoiceId).isNotNull();

            // Verify database data after invoice creation
            CommercialInvoiceEntity storedInvoice = commercialInvoiceService.findById(invoiceId).get();
            assertThat(storedInvoice).isNotNull();
            assertThat(storedInvoice.getInvoiceNumber()).isEqualTo(newInvoice.getInvoiceNumber());
            assertThat(storedInvoice.getAmount()).isEqualTo(newInvoice.getAmount());
        }
    }

    private static FieldValueMapper<String> alwaysStringFieldMapper() {
        return (field, fieldType) -> RandomJava.nextString();
    }

}
