            .invoiceDate(faker.date().past(30, "NOW"))
            .totalValue(faker.number().randomBigDecimal(2, 2))
            .build();

    // Se envía la solicitud POST con los datos falsos
    String response = restTemplate.postForObject("/invoices", invoiceRequest, String.class);

    // Se verifica el código de estado HTTP
    Assertions.assertEquals(HttpStatus.CREATED.value(), response.startsWith("2"));

    // Comprueba que la factura fue creada correctamente en Oracle EBS
    EntityManager entityManager = entityManagerFactory.createEntityManager();
    List<Invoice> invoices = entityManager.createQuery("SELECT i FROM Invoice i WHERE i.customerId = :customer_id AND i.invoiceDate = :invoice_date")
            .setParameter("customer_id", invoiceRequest.getCustomerId())
            .setParameter("invoice_date", invoiceRequest.getInvoiceDate().toInstant())
            .getResultList();
    Assertions.assertNotEmpty(invoices);
    Assertions.assertEquals(invoices.get(0).getTotalValue(), invoiceRequest.getTotalValue());
    entityManager.close();
  }

