4. Crea un nuevo archivo llamado `server.ts` en la raíz de tu proyecto, y agrega el siguiente código:

```typescript
import express, { NextFunction, Request, Response } from 'express';
import 'dotenv/config';
import jwt from 'jsonwebtoken';
import session from 'express-session';
import cookieParser from 'cookie-parser';
import passport from 'passport';
import { Strategia } from 'passport-jwt';

const PORT = process.env.PORT || 3000;
const app = express();

// Configuración de cookies y sesiones
app.use(cookieParser());
app.use(
    session({
        secret: process.env.SESSION_SECRET,
        resave: false,
        saveUninitialized: false,
    })
);

// Configuración de passport
passport.use(
    new Strategia.Strategy(
        {
            jwtFromRequest: (req: Request) =>
                req?.cookies?.jwt || req?.headers?.authorization?.replace('Bearer ', ''),
            secretOrKey: process.env.JWT_SECRET,
            algorithms: ['HS256'],
        },
        (jwt_payload, done) => done(null, jwt_payload)
    )
);

passport.serializeUser((user, done) => done(null, user.id));
passport.deserializeUser((id, done) => done(null, { id }));

app.use(express.json());
app.use(express.urlencoded({ extended: true }));
app.use(express.static('public')); // Para servir archivos estáticos.
app.use(passport.initialize());
app.use(passport.session());

// Endpoints

app.get('/', (req: Request, res: Response) => {
    res.send('Exemplo servidor TypeScript Express');
});

// Acceso protegido
app.get(
    '/protected',
    passport.authenticate('jwt', { session: false }),
    (req: Request, res: Response) => {
        res.send(`Hola ${req.user.id}`);
    }
);

// Configuración del servidor
app.listen(PORT, () => {
    console.log(`Servidor http escuchando en http://localhost:${PORT}`);
});
```

