              if (
                (method.type === 'MethodDefinition' && method.value.body.type === 'BlockStatement') ||
                method.type === 'ClassProperty'
              ) {
                const methodBody = method.value.body || method.value;

                const isStateMutator = !isAllowedMethod(method.key.name, 'value') &&
                  methodBody.body.some(node => {
                    const isAssignment = node.type === 'AssignmentExpression';
                    const isObjectProperty = node.type === 'ObjectProperty';
                    const isCallExpression = node.type === 'CallExpression';

                    return (
                      (isAssignment && isObjectProperty && node.object.type === 'ThisExpression') ||
                      (isCallExpression && node.callee.type === 'MemberExpression' && node.callee.object.type === 'ThisExpression' && node.callee.property.name === 'push' || node.callee.property.name === 'splice')
                    );
                  });

                if (isStateMutator) {
                  newStateMethods.push(method.key.name);
                }
              }
            });

            // Buscamos métodos llamados internamente que también lo hacen
            VueInstance.body.body.forEach(method => {
              if (
                (method.type === 'MethodDefinition' && method.value.body.type === 'BlockStatement') ||
                method.type === 'ClassProperty'
              ) {
                const methodBody = method.value.body || method.value;

                methodBody.body.forEach(node => {
                  if (node.type === 'ExpressionStatement' && node.expression.type === 'CallExpression') {
                    const { callee } = node.expression;

                    if (callee.type === 'MemberExpression' && callee.object.type === 'ThisExpression') {
                      const { name: methodName } = callee.property;

                      if (newStateMethods.includes(methodName)) {
                        context.report({
                          node,
                          message: `Method "${methodName}" modifies the internal state and is called in "${method.key.name}".`,
                          fix(fixer) {
                            const call = fixer.replaceTextRange(node.range, `${method.key.name}().then(() => { ${fixer.insertTextBefore(node, 'await ')} });`);

                            return [
                              fixer.insertTextAfter(method.key, '\n\nasync '),
                              call
                            ];
                          }
                        });
                      }
                    }
                  }
                });
              }
            });
          }
        });
      }
    };
  }
};

module.exports = { VuexModuleRule };
```

