    " vue/updated-hook-modify-state ": {
      " meta ": {
        " docs ": {
          " description ": "Prevent methods in the updated lifecycle hook from modifying the internal state of the component."
        },
        " schema ": [
          {
            " type ": "object",
            " properties ": {
              " allowedDependencies ": {
                " type ": "array",
                " items ": {
                  " type ": "string"
                },
                " minItems ": 0,
                " uniqueItems ": true
              }
            }
          }
        ],
        " fixable ": "code"
      },
      " create (context) {
        const allowedDependencies = (context.options[0] || {}).allowedDependencies || [];

        return {
          "UpdatedHook" (node) {
            if (node.type !== "FunctionExpression" || !node.params.some(param => param.name === "next")) {
              return;
            }

            const updateMethods = node.body.body.filter(stmt => {
              if (stmt.type !== "ExpressionStatement") {
                return false;
              }

              const methodCall = stmt.expression;

              if (!methodCall.callee || methodCall.callee.type !== "MemberExpression") {
                return false;
              }

              const callee = methodCall.callee.object;
              const methodName = methodCall.callee.property.name;

              return (methodName === "push" || methodName === "splice"
                      || methodName === "filter" || methodName === "map"
                      || methodName === "reverse" || methodName === "sort"
                      || (allowedDependencies.includes(callee.name) && methodName === "update")))
                      && methodCall.arguments.some(arg => arg.type === "ObjectExpression");
          }

          "expressionStatement" (node) {
            if (node.parent.type !== "BlockStatement") {
              return;
            }

            const updateMethod = node.expression;

            if (updateMethod.type !== "MemberExpression" || !updateMethod.object || updateMethod.object.type !== "ThisExpression") {
              return;
            }

            const methodName = updateMethod.property.name;
            const allowed = allowedDependencies.includes(updateMethod.object.name) && methodName === "update";

            if (methodName === "push" || methodName === "splice"
                || methodName === "filter" || methodName === "map"
                || methodName === "reverse" || methodName === "sort"
                || allowed) {
              return;
            }

            context.report({
              node,
              message: `'${methodName}' modifies state in updated lifecycle hook.` 
            });
          }
        };
      }
    }
  }
}
```

