       // Regla personalizada para ciclo de vida actualizado
       "vue/custom-lifecycle-hooks-modifiers": "error"
     },
     "plugins": ["vue"]
   }
   ```

3. Creamos una nueva regla personalizada para `eslint-plugin-vue` llamada `vue/custom-lifecycle-hooks-modifiers`, y agreguémosle la siguiente descripción y validación:

   ```javascript
   module.exports = {
     rules: {
       "vue/custom-lifecycle-hooks-modifiers": {
         meta: {
           docs: {
             description:
               "Prohibe métodos en hooks de ciclo de vida actualizados que modifiquen el estado interno del componente",
           },
         },
         create(config, context) {
           return {
             NamePath(node) {
               // Comprueba los métodos en los hooks de ciclo de vida actualizados
               if (
                 node.parent.type === "MethodDefinition" &&
                 context.getAncestor(node, n => n.type === "Hook")?.methodName === "updated"
               ) {
                 // Prohíbe métodos que modifiquen directamente el estado interno del componente
                 const stateModifiers = ["state", "setData", "setDataField"];

                 if (stateModifiers.some(modifier => node.key.name === modifier)) {
                   context.report({
                     node,
                     message:
                       `Método '${node.key.name}' en '${node.parent.parent.key.name}' no puede modificar directamente el estado del componente`,
                   });
                 }

                 // Comprueba llamadas a métodos internos que también modifiquen el estado
                 const internalMethods = ["updateData", "updateDataField"];

                 if (node.body.body.some(bodyNode => internalMethods.includes(bodyNode.callee.name))) {
                   context.report({
                     node: bodyNode,
                     message:
                       `Método '${bodyNode.callee.name}' que modifica el estado no debe ser llamado desde '${node.key.name}' en '${node.parent.parent.key.name}'`,
                   });
                 }
               }
             },
           };
         },
       },
     },
   };
   ```

Eso es todo, ahora tendremos una regla personalizada para detectar métodos dentro de los hooks de ciclo de vida actualizados que modifiquen directamente el estado del componente y métodos internos llamados por esos métodos.

